shellCommands.command:
mkdir -p /tmp/smoke && cat > src/__smoke.test.tsx <<'EOF'
import { test, expect } from 'vitest';
import { renderToString } from 'react-dom/server';
import React from 'react';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from './App';

test('renders calendar', () => {
  const html = renderToString(<ThemeProvider theme="light"><App /></ThemeProvider>);
  expect(html).toContain('Select a date');
  expect(html).toContain('No date selected');
  console.log('has grid:', /role="grid"|gridcell/.test(html), 'len', html.length);
});
EOF
timeout 180 npx vitest run src/__smoke.test.tsx 2>&1 | tail -30; rm -f src/__smoke.test.tsx; rm -rf /tmp/smoke

